CREATE TABLE institution_collections (tenant_id uuid NOT NULL REFERENCES tenants(id),id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 512),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE institution_tokens (tenant_id uuid NOT NULL,id uuid NOT NULL,issuer_user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE CHECK(token_hash ~ '^[a-f0-9]{64}$'),scopes jsonb NOT NULL,collections jsonb NOT NULL,artworks jsonb NOT NULL,expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false,window_start timestamptz NOT NULL DEFAULT now(),window_count integer NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,id));
CREATE TABLE institution_batches (tenant_id uuid NOT NULL,id uuid NOT NULL,collection_id uuid NOT NULL,actor_user_id uuid NOT NULL REFERENCES users(id),request_id uuid NOT NULL,payload_sha256 text NOT NULL,state text NOT NULL CHECK(state IN ('complete','rolled-back')),results jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,actor_user_id,request_id),FOREIGN KEY(tenant_id,collection_id) REFERENCES institution_collections(tenant_id,id));
CREATE TABLE institution_inventory (tenant_id uuid NOT NULL,id uuid NOT NULL,collection_id uuid NOT NULL,artwork_id uuid NOT NULL,batch_id uuid NOT NULL,metadata jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,collection_id) REFERENCES institution_collections(tenant_id,id),FOREIGN KEY(tenant_id,artwork_id) REFERENCES artworks(tenant_id,id),FOREIGN KEY(tenant_id,batch_id) REFERENCES institution_batches(tenant_id,id));
CREATE TRIGGER institution_inventory_immutable BEFORE UPDATE OR DELETE ON institution_inventory FOR EACH ROW EXECUTE FUNCTION immutable_revision();
CREATE TABLE institution_inventory_state (tenant_id uuid NOT NULL,id uuid NOT NULL,active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,id) REFERENCES institution_inventory(tenant_id,id));
CREATE TABLE institution_history (sequence bigserial UNIQUE NOT NULL,tenant_id uuid NOT NULL,id uuid NOT NULL,collection_id uuid NOT NULL,inventory_id uuid NOT NULL,action text NOT NULL CHECK(action IN ('imported','rolled-back')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,inventory_id) REFERENCES institution_inventory(tenant_id,id));
CREATE TRIGGER institution_history_immutable BEFORE UPDATE OR DELETE ON institution_history FOR EACH ROW EXECUTE FUNCTION immutable_revision();
CREATE TABLE institution_pages (tenant_id uuid NOT NULL,id uuid NOT NULL,actor_user_id uuid NOT NULL REFERENCES users(id),collection_id uuid NOT NULL,filter text NOT NULL,items jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes',PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,collection_id) REFERENCES institution_collections(tenant_id,id));
